// SigmaOS Sovereign Thousands Distro Components Subsystem
// Cataloging and executing 1024+ Linux & BSD distro components across 10 categories.

use std::format;
use std::string::String;
use std::vec::Vec;

/// Distro Component Categories
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DistroComponentCategory {
    KernelScheduler,
    FilesystemsStorage,
    SecurityHardening,
    PackageManagement,
    NetworkingFirewall,
    InitAndSupervisor,
    UserlandUtilities,
    DesktopAndMedia,
    DriversHardware,
    VirtualizationContainers,
}

impl DistroComponentCategory {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::KernelScheduler => "KernelScheduler",
            Self::FilesystemsStorage => "FilesystemsStorage",
            Self::SecurityHardening => "SecurityHardening",
            Self::PackageManagement => "PackageManagement",
            Self::NetworkingFirewall => "NetworkingFirewall",
            Self::InitAndSupervisor => "InitAndSupervisor",
            Self::UserlandUtilities => "UserlandUtilities",
            Self::DesktopAndMedia => "DesktopAndMedia",
            Self::DriversHardware => "DriversHardware",
            Self::VirtualizationContainers => "VirtualizationContainers",
        }
    }
}

/// Distro Component Item Record
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DistroComponentItem {
    pub id: u32,
    pub name: String,
    pub category: DistroComponentCategory,
    pub origin_distro: String,
    pub description: String,
    pub enabled: bool,
    pub execution_count: u64,
}

